<script setup lang="ts">
import { ElMessageBox, ElMessage } from '@/i18n'
import { t as uiText } from '../../../../packages/localization/language'

import PageHeader from '@/components/PageHeader.vue'
import {ref,onMounted} from 'vue'
import ProviderAffiliation from '../../../../packages/admin-ui/components/ProviderAffiliation.vue'
import { beliefLabel } from '../../../../packages/admin-ui/affiliation'

import {useAuthStore} from '@/stores/auth'
import client from '@/api/client'
const auth=useAuthStore(),rows=ref<any[]>([]),selected=ref<any>(),history=ref<any[]>([]),status=ref('submitted'),page=ref(1),busy=ref(false),note=ref(''),error=ref('')
const states:Record<string,string>={draft:'草稿',submitted:'待审核',rejected:'已退回',approved:'已通过'}
async function load(){error.value='';try{rows.value=(await client.get<{list:any[]}>(`/auth/onboarding/reviews?status=${status.value}&page=${page.value}`)).list}catch(e){error.value=(e as Error).message}}
async function select(row:any){selected.value=row;note.value='';try{history.value=(await client.get<{list:any[]}>('/auth/onboarding/history?id='+row.id)).list}catch(e){error.value=(e as Error).message}}
async function review(approve:boolean){if(approve&&!selected.value?.profile?.traditionCodes?.length){error.value='此申请尚未选择标准宗派或信俗，请退回补充后再审核';return}if(!approve&&!note.value.trim()){error.value='请填写退回原因';return}try{await ElMessageBox.confirm((approve ? uiText('确认资料及授权有效？通过后将开通对应业务身份。') : uiText('确认退回，申请人可补充材料后重新提交。')),uiText('审核确认'));busy.value=true;await client.post('/auth/onboarding/review',{id:selected.value.id,revision:selected.value.revision,approve,note:note.value});ElMessage.success(uiText('审核结果已保存'));selected.value=undefined;await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=e instanceof Error?e.message:'操作未完成'}finally{busy.value=false}}
async function download(id:string){try{const r=await fetch('/api/v1/auth/onboarding/evidence?id='+encodeURIComponent(id),{headers:{Authorization:'Bearer '+auth.token}});if(!r.ok||r.headers.get('content-type')?.includes('json'))throw new Error('无权读取材料');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='认证材料';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
onMounted(load)
</script>
<template><div class="df-page"><PageHeader :title='$t("认证与入驻审核")' :subtitle='$t("独立大师认证、寺院机构入驻；寺院纳管大师继续由所属寺院管理。")' /><p v-if="error" role="alert">{{$t(error)}}</p><div class="df-card"><div class="filter-bar"><el-select v-model="status" style="width:200px" :aria-label='$t("审核状态")' @change="page=1;load()"><el-option v-for="(label,value) in states" :key="value" :label="$t(label)" :value="value"/></el-select><el-button @click="load">{{ $t("刷新") }}</el-button></div><el-table :data="rows" @row-click="select"><el-table-column :label='$t("申请类型")'><template #default="{row}">{{$t((row.kind==='master' ? $t('独立大师') : $t('寺院入驻')))}}</template></el-table-column><el-table-column prop="profile.name" :label='$t("名称")'/><el-table-column :label='$t("状态")'><template #default="{row}">{{$t(states[row.status])}}</template></el-table-column><el-table-column prop="updatedAt" :label='$t("更新时间")'/><el-table-column :label='$t("操作")'><template #default="{row}"><el-button @click.stop="select(row)">{{ $t("查看材料") }}</el-button></template></el-table-column></el-table><div class="aui-pagination"><el-button :disabled="page<=1" @click="page--;load()">{{ $t("上一页") }}</el-button><el-button :disabled="rows.length<50" @click="page++;load()">{{ $t("下一页") }}</el-button></div></div>
<el-dialog :model-value="!!selected" :title='$t("申请资料")' width="min(720px,94vw)" @close="selected=undefined" append-to-body><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item v-for="(label,key) in {name:'名称',legalName:'本人／经办人',contact:'联系方式',region:'地区',address:'地址',belief:'主信仰',sect:'宗派补充说明',position:'职务',registrationNumber:'登记证号',description:'介绍'}" :key="key" :label="$t(label)">{{$t((key==='belief' ? beliefLabel(selected.profile[key]) : (selected.profile[key] || '—')))}}</el-descriptions-item></el-descriptions><div class="application-affiliation"><ProviderAffiliation :belief="selected.profile.belief" :codes="selected.profile.traditionCodes || []" readonly/><p v-if="!selected.profile.traditionCodes?.length" role="status">{{ $t('此申请尚未选择标准宗派或信俗，请退回补充后再审核') }}</p></div><p><el-button v-for="(id,i) in selected.profile.evidenceIds" :key="id" @click="download(id)">{{ $t("查看证明 ") }}{{$t((Number(i) + 1))}}</el-button></p><p v-for="(event,i) in history" :key="i">{{$t(event.at)}} · {{$t((({save:'保存草稿',submit:'提交审核',approved:'审核通过',rejected:'退回补充'} as Record<string,string>)[event.action] || event.action))}} · {{event.note}}</p><template v-if="selected.status==='submitted'"><el-input v-model="note" type="textarea" maxlength="1000" :placeholder='$t("审核说明；退回时必填")'/><p><el-button :disabled="busy" @click="review(false)">{{ $t("退回补充") }}</el-button><el-button type="primary" :disabled="busy || !selected.profile.traditionCodes?.length" @click="review(true)">{{ $t("审核通过") }}</el-button></p></template><p v-else>{{ $t("审核意见：") }}{{$t((selected.reviewNote || $t('无')))}}</p></template></el-dialog></div></template>

<style scoped>.application-affiliation{margin:20px 0;padding:16px;background:var(--admin-bg);border-radius:8px}.application-affiliation>p{color:var(--admin-warning);font-size:13px;line-height:1.7}</style>
